// Runnable programs (compiled with g++ -std=c++20 -Wall -Wextra; outputs are exact).
const CODE_A8 = `#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <functional>
#include <queue>
#include <string>
#include <tuple>
#include <vector>

// 8-directional grid. Integer costs: straight 70, diagonal 99 (99/70 ~ 1.4143).
const std::vector<std::string> grid = {
    "........................................",
    "...........#................#...........",
    "...........#................#...........",
    "...........#.......#........#...........",
    "...........#.......#........#...........",
    "...........#.......#........#...........",
    "..S........#.......#........#........G..",
    "...........#.......#........#...........",
    "...........#.......#....................",
    "...................#....................",
    "...................#....................",
    "...................#....................",
};
const int R = int(grid.size()), C = int(grid[0].size());
const int SR = 6, SC = 2, GR = 6, GC = 37;

enum class H { Zero, Manhattan, Euclid, Octile };

int heuristic(H kind, int r, int c) {
    int dx = std::abs(c - GC), dy = std::abs(r - GR);
    switch (kind) {
        case H::Zero: return 0;
        case H::Manhattan: return 70 * (dx + dy);  // overestimates diagonals!
        case H::Euclid: return int(70 * std::sqrt(double(dx * dx + dy * dy)));
        case H::Octile: return 70 * std::max(dx, dy) + 29 * std::min(dx, dy);
    }
    return 0;
}

// Returns {path cost, cells expanded}. weight multiplies h; preferDeep breaks
// f-ties toward larger g (closer to the goal).
std::pair<int, int> search(H kind, double weight, bool preferDeep, bool greedy = false) {
    std::vector<int> g(R * C, 1 << 30);
    std::vector<bool> closed(R * C, false);
    using Item = std::tuple<long long, int, int>;  // (priority, tie key, cell)
    std::priority_queue<Item, std::vector<Item>, std::greater<>> open;
    auto push = [&](int cell) {
        int h = heuristic(kind, cell / C, cell % C);
        long long f = greedy ? h : g[cell] + std::llround(weight * h);
        open.push({f, preferDeep ? -g[cell] : g[cell], cell});
    };
    int start = SR * C + SC, goal = GR * C + GC;
    g[start] = 0;
    push(start);
    int expanded = 0;
    while (!open.empty()) {
        auto [f, tie, cell] = open.top();
        open.pop();
        if (closed[cell]) continue;
        closed[cell] = true;
        ++expanded;
        if (cell == goal) return {g[goal], expanded};  // stop when the goal is POPPED
        int r = cell / C, c = cell % C;
        for (int dr = -1; dr <= 1; ++dr)
            for (int dc = -1; dc <= 1; ++dc) {
                int nr = r + dr, nc = c + dc;
                if ((dr == 0 && dc == 0) || nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
                if (grid[nr][nc] == '#') continue;
                // No corner cutting: a diagonal move needs both side cells open.
                if (dr != 0 && dc != 0 && (grid[r][nc] == '#' || grid[nr][c] == '#')) continue;
                int next = nr * C + nc;
                int cost = (dr != 0 && dc != 0) ? 99 : 70;
                if (g[cell] + cost < g[next]) {
                    g[next] = g[cell] + cost;
                    push(next);
                }
            }
    }
    return {-1, expanded};
}

int main() {
    struct Row { const char* name; H h; double w; bool deep; bool greedy; };
    const Row rows[] = {
        {"Dijkstra (h = 0)", H::Zero, 1.0, true, false},
        {"A*, Euclidean", H::Euclid, 1.0, true, false},
        {"A*, octile", H::Octile, 1.0, true, false},
        {"A*, octile, ties -> small g", H::Octile, 1.0, false, false},
        {"A*, Manhattan (inadmissible)", H::Manhattan, 1.0, true, false},
        {"weighted A*, octile, w = 1.5", H::Octile, 1.5, true, false},
        {"weighted A*, octile, w = 3", H::Octile, 3.0, true, false},
        {"greedy best-first, octile", H::Octile, 1.0, true, true},
    };
    std::printf("%-30s %10s %9s\\n", "search", "path cost", "expanded");
    for (const auto& row : rows) {
        auto [cost, expanded] = search(row.h, row.w, row.deep, row.greedy);
        std::printf("%-30s %10.3f %9d\\n", row.name, cost / 70.0, expanded);
    }
}`;
