const CODE_INC = `#include <cstdio>
#include <functional>
#include <queue>
#include <utility>
#include <vector>

// S=0, A=1, C=2, G=3.  Edges: S->A 1, A->C 1, S->C 3, C->G 3.  Best: S-A-C-G = 5.
// h = {0, 4, 0, 0} is admissible (never above the true cost to G)
// but inconsistent: h(A) = 4 > w(A, C) + h(C) = 1.
struct Edge { int to, w; };

int astar(bool reopen, int& expansions) {
    std::vector<std::vector<Edge>> adj = {{{1, 1}, {2, 3}}, {{2, 1}}, {{3, 3}}, {}};
    const int h[] = {0, 4, 0, 0};
    std::vector<int> g(4, 1 << 30);
    std::vector<bool> closed(4, false);
    using Item = std::pair<int, int>;  // (f, vertex)
    std::priority_queue<Item, std::vector<Item>, std::greater<>> open;
    g[0] = 0;
    open.push({h[0], 0});
    expansions = 0;
    while (!open.empty()) {
        auto [f, u] = open.top();
        open.pop();
        if (closed[u] || f > g[u] + h[u]) continue;  // already closed, or stale
        closed[u] = true;
        ++expansions;
        if (u == 3) return g[3];
        for (auto [v, w] : adj[u]) {
            if (g[u] + w >= g[v]) continue;
            if (closed[v] && !reopen) continue;  // the "never touch closed" rule
            g[v] = g[u] + w;
            closed[v] = false;  // (re)open v
            open.push({g[v] + h[v], v});
        }
    }
    return -1;
}

int main() {
    int e1, e2;
    int noReopen = astar(false, e1);
    int withReopen = astar(true, e2);
    std::printf("closed set, no reopening: cost %d (%d expansions)\\n", noReopen, e1);
    std::printf("with reopening:           cost %d (%d expansions)\\n", withReopen, e2);
}`;
const OUT_INC = `closed set, no reopening: cost 6 (4 expansions)
with reopening:           cost 5 (5 expansions)`;
const CODE_FLOW = `#include <cstdio>
#include <queue>
#include <string>
#include <vector>

// One search from the goal serves every unit: a distance field plus a flow field.
int main() {
    std::vector<std::string> grid = {
        "............",
        "..####......",
        ".....#..##..",
        ".....#...#G.",
        "..#..#...#..",
        "..#......#..",
        "............",
    };
    const int R = int(grid.size()), C = int(grid[0].size());
    const int dr[] = {-1, 1, 0, 0}, dc[] = {0, 0, -1, 1};
    const char arrow[] = {'^', 'v', '<', '>'};

    // 1. BFS from the goal (unit costs; use Dijkstra for weighted terrain).
    std::vector<std::vector<int>> dist(R, std::vector<int>(C, -1));
    std::queue<std::pair<int, int>> q;
    dist[3][10] = 0;
    q.push({3, 10});
    while (!q.empty()) {
        auto [r, c] = q.front();
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
            if (grid[nr][nc] == '#' || dist[nr][nc] != -1) continue;
            dist[nr][nc] = dist[r][c] + 1;
            q.push({nr, nc});
        }
    }

    // 2. Flow field: every cell points at its lowest-distance neighbor.
    std::vector<std::string> flow = grid;
    for (int r = 0; r < R; ++r)
        for (int c = 0; c < C; ++c) {
            if (grid[r][c] != '.' || dist[r][c] < 0) continue;
            int best = -1;
            for (int k = 0; k < 4; ++k) {
                int nr = r + dr[k], nc = c + dc[k];
                if (nr < 0 || nr >= R || nc < 0 || nc >= C || dist[nr][nc] < 0) continue;
                if (best == -1 || dist[nr][nc] < dist[r + dr[best]][c + dc[best]]) best = k;
            }
            flow[r][c] = arrow[best];
        }
    for (int r = 0; r < R; ++r) {
        for (int c = 0; c < C; ++c)
            if (grid[r][c] == '#') std::printf("  #");
            else std::printf("%3d", dist[r][c]);
        std::printf("    %s\\n", flow[r].c_str());
    }

    // 3. Units just follow arrows: O(1) work per unit per step, no searching.
    const int units[][2] = {{0, 0}, {6, 0}, {6, 11}};
    for (const auto& u : units) {
        int r = u[0], c = u[1], steps = 0;
        while (grid[r][c] != 'G') {
            char a = flow[r][c];
            int k = a == '^' ? 0 : a == 'v' ? 1 : a == '<' ? 2 : 3;
            r += dr[k]; c += dc[k]; ++steps;
        }
        std::printf("unit from (%d,%d): %d steps (field says %d)\\n", u[0], u[1], steps, dist[u[0]][u[1]]);
    }
}`;
